for slug, policy in policies.items():
 body=f'<section class="section prose-page"><p class="eyebrow">TECH COMPASS · SITE INFORMATION</p><h1>{e(policy["title"])}</h1><p class="small">Updated {e(site_info["updated"])}</p><p class="intro">{e(policy["intro"])}</p>'
 body+=''.join(f'<h2>{e(title)}</h2><p>{e(text)}</p>' for title,text in policy['sections'])
 body+=f'<p class="contact-action"><a class="button" href="mailto:{e(site_info["contact_email"])}">Email {e(site_info["operator"])}</a></p>'
 if slug=='privacy':body+='<p class="small">Provider information: <a href="https://openai.com/policies/privacy-policy/">OpenAI privacy policy</a> · <a href="https://www.cloudflare.com/privacypolicy/">Cloudflare privacy policy</a> · <a href="https://www.apple.com/legal/privacy/">Apple privacy policy</a></p>'
 page('/'+slug+'/',policy['title'],body+'</section>')
