(OUT/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12" fill="#0b1c2c"/><path d="M32 5L43 32 32 59 21 32Z" fill="#c4a46a"/><path d="M32 14v36l-7-18z" fill="#f4f0e7"/></svg>')

paths=sorted('/'+str(p.parent.relative_to(OUT)).replace('\\','/').strip('.')+'/' for p in OUT.rglob('index.html') if p.parent.name not in ('404','search'))
